LOGO_EMBUTIDO = ''
def recurso_embutido(valor):
 return zlib.decompress(base64.b64decode(valor))

BASE=Path(__file__).resolve().parent
DB=Path(os.environ.get('GDS_DB_PATH',str(BASE/'ocorrencia_ponto.sqlite3')))
EMPRESAS={
 'GDSLOG SOLUCOES LTDA FILIAL':'29.727.360/0002-52',
 'CDSP2 LOGISTICA LTDA':'55.990.578/0001-24',
 'GDS LOGISTICA FILIAL':'16.637.947/0002-29',
 'GDS LOG SOLUÇÕES LTDA':'29.727.360/0001-71',
 'GDS LOGISTICA LTDA':'16.637.947/0001-48',
}
REGISTROS=['Registro a conferir','Entrada','Saída Intervalo','Retorno Intervalo','Saída']
MOTIVOS=['ESQUECEU DE REGISTRAR','APP COM ERRO','SEM ACESSO AO APP','APP INDISPONÍVEL','FALHA NA CONEXÃO COM A INTERNET','CELULAR SEM BATERIA','FALHA NA SINCRONIZAÇÃO DO PONTO','OUTROS – INFORMAR MOTIVO']
def normal(v):
 return ' '.join(str(v or '').strip().upper().split())
def numeros(v):
 return re.sub(r'\D','',str(v or ''))
def empresa_normalizada(v):
 n=normal(v)
 sem_acento=lambda t: ''.join(c for c in unicodedata.normalize('NFKD',t) if not unicodedata.combining(c))
 for nome in EMPRESAS:
  if sem_acento(normal(nome))==sem_acento(n): return nome
 return n

# Código do aplicativo pode ficar PÚBLICO. Banco SQLite fica em repositório de DADOS SEPARADO e PRIVADO.
# Nunca enviar arquivos SQLite ou dados de colaboradores ao repositório público.
_GH_LOCK = threading.RLock()

def _segredo(nome, padrao=''):
 try: return str(st.secrets.get(nome, os.getenv(nome, padrao))).strip()
 except Exception: return str(os.getenv(nome, padrao)).strip()

def _gh_config():
 token=_segredo('GITHUB_TOKEN')
 repo=_segredo('GITHUB_REPO', 'anaflav06/ocorrencia-de-ponto')
 senha=_segredo('APP_PASSWORD')
 if not token or not senha:
  raise RuntimeError('Configure APP_PASSWORD e GITHUB_TOKEN nos Secrets.')
 if repo.count('/') != 1:
  raise RuntimeError('GITHUB_REPO deve ter formato usuario/repositorio.')
 if repo.lower() != 'anaflav06/ocorrencia-de-ponto':
  raise RuntimeError('Repositório inesperado. Confira GITHUB_REPO nos Secrets.')
 info=_gh_request('GET',f'https://api.github.com/repos/{repo}',token)
 if not info:
  raise RuntimeError('Não foi possível acessar o repositório. Confira o token e as permissões Contents: Read and write.')
 return token,repo

# Protege o banco ANTES de enviá-lo ao GitHub público. A chave é derivada
# dos Secrets já existentes, sem DB_ENCRYPTION_KEY adicional.
# ATENÇÃO: alterar o token ou a senha sem migrar o banco impede sua leitura.
def _chave_db(token):
 senha=_segredo('APP_PASSWORD')
 return hashlib.pbkdf2_hmac('sha256', (token + '\x00' + senha).encode(), b'GDS-PONTO-PUBLICO-DB-v1', 260000, dklen=32)

def _criptografar_db(raw,token):
 nonce=os.urandom(12)
 return b'GDSENC01'+nonce+AESGCM(_chave_db(token)).encrypt(nonce,raw,b'GDS-OCORRENCIA-PONTO')

def _descriptografar_db(payload,token):
 if not payload.startswith(b'GDSENC01') or len(payload)<37:
  raise RuntimeError('Banco remoto não está criptografado no formato esperado. Nenhum dado foi sobrescrito.')
 try:
  return AESGCM(_chave_db(token)).decrypt(payload[8:20],payload[20:],b'GDS-OCORRENCIA-PONTO')
 except Exception as exc:
  raise RuntimeError('Não foi possível abrir o banco protegido. Confira se o token e APP_PASSWORD são os mesmos usados ao salvar. Não sobrescreva o banco.') from exc

def _gh_request(method,url,token,data=None):
 headers={'Authorization':f'Bearer {token}','Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28','User-Agent':'gds-ocorrencia-ponto'}
 if data is not None:
  headers['Content-Type']='application/json'
  data=json.dumps(data).encode('utf-8')
 req=urllib.request.Request(url,data=data,headers=headers,method=method)
 try:
  with urllib.request.urlopen(req,timeout=25) as response:
   return json.loads(response.read().decode('utf-8'))
 except urllib.error.HTTPError as exc:
  if exc.code==404 and method=='GET': return None
  if exc.code in (409,422): raise RuntimeError('Conflito ao salvar no GitHub. Recarregue o aplicativo e repita a operação.') from exc
  raise RuntimeError(f'GitHub retornou HTTP {exc.code}. Verifique token, repositório privado e permissões.') from exc

def _gh_url(repo):
 from urllib.parse import quote
 return f'https://api.github.com/repos/{quote(repo,safe="/")}/contents/dados/ocorrencia_ponto.sqlite3.enc'

def _baixar_db(token,repo):
 info=_gh_request('GET',_gh_url(repo),token)
 if info is None: return None,None
 if info.get('type')!='file': raise RuntimeError('Arquivo de dados remoto inválido.')
 # Download pelo endpoint de conteúdo, que fornece base64.
 payload=base64.b64decode(info['content'].replace('\n',''))
 return _descriptografar_db(payload,token),info['sha']

def _enviar_db(token,repo,raw,sha):
 dados={'message':'Atualizar base de ocorrências GDS','content':base64.b64encode(_criptografar_db(raw,token)).decode('ascii')}
 if sha: dados['sha']=sha
 return _gh_request('PUT',_gh_url(repo),token,dados)

@contextmanager
def conectar():
 # Uma execução por vez no processo; cada operação relê a versão remota.
 with _GH_LOCK:
  token,repo=_gh_config()
  raw,sha=_baixar_db(token,repo)
  with tempfile.TemporaryDirectory(prefix='gds_db_') as temp:
   local=Path(temp)/'ponto.sqlite3'
   if raw is not None: local.write_bytes(raw)
   con=sqlite3.connect(str(local),timeout=30)
   try:
    con.execute("CREATE TABLE IF NOT EXISTS colaboradores (nome TEXT PRIMARY KEY, cargo TEXT, cpf TEXT, empresa TEXT, ativo INTEGER DEFAULT 1, origem TEXT DEFAULT 'planilha')")
    con.execute('CREATE TABLE IF NOT EXISTS configuracoes (chave TEXT PRIMARY KEY, valor TEXT)')
    con.execute('CREATE TABLE IF NOT EXISTS importacoes (id INTEGER PRIMARY KEY AUTOINCREMENT, data TEXT, arquivo TEXT, total INTEGER, ativos INTEGER)')
    con.commit()
    before=local.read_bytes()
    try:
     yield con
     con.commit()
    except BaseException:
     con.rollback()
     raise
    finally:
     con.close()
    after=local.read_bytes()
    if after!=before or raw is None:
     # Detecta edições remotas simultâneas antes de sobrescrever.
     current=_gh_request('GET',_gh_url(repo),token)
     remote_sha=current['sha'] if current else None
     if remote_sha!=sha: raise RuntimeError('Outro usuário atualizou os dados. Recarregue e repita para evitar perda de informações.')
     _enviar_db(token,repo,after,sha)
   finally:
    try: con.close()
    except Exception: pass

def importar(dados,arquivo):
 col={normal(x):x for x in dados.columns}
 campos=['NOME','CPF','CARGO','EMPRESA','ATIVO']
 if any(x not in col for x in campos):
  raise ValueError('Planilha precisa conter as colunas Nome, CPF, Cargo, Empresa e Ativo.')
 registros={}
 for _,r in dados.iterrows():
  nome=normal(r[col['NOME']]) if pd.notna(r[col['NOME']]) else ''
  if not nome: continue
  cpf=numeros(r[col['CPF']]) if pd.notna(r[col['CPF']]) else ''
  cargo=normal(r[col['CARGO']]) if pd.notna(r[col['CARGO']]) else ''
  empresa=empresa_normalizada(r[col['EMPRESA']]) if pd.notna(r[col['EMPRESA']]) else ''
  ativo=1 if str(r[col['ATIVO']]).strip() in ('1','1.0') else 0
  registros[nome]=(nome,cargo,cpf,empresa,ativo,'planilha')
 if not registros: raise ValueError('Nenhum colaborador encontrado na planilha.')
 with conectar() as con:
  # Nova importação substitui a base da planilha. Cadastros manuais são preservados.
  con.execute("DELETE FROM colaboradores WHERE origem='planilha'")
  con.executemany('INSERT OR REPLACE INTO colaboradores(nome,cargo,cpf,empresa,ativo,origem) VALUES (?,?,?,?,?,?)',list(registros.values()))
  con.execute('INSERT INTO importacoes(data,arquivo,total,ativos) VALUES (?,?,?,?)',(datetime.now().isoformat(timespec='seconds'),arquivo,len(registros),sum(v[4] for v in registros.values())))
 return len(registros),sum(v[4] for v in registros.values())

