def ler_arquivo(arquivo):
 b=io.BytesIO(arquivo.getvalue())
 if arquivo.name.lower().endswith('.csv'):
  return pd.read_csv(b,sep=';',dtype=str,encoding='utf-8-sig',keep_default_na=False)
 return pd.read_excel(b,dtype=str,keep_default_na=False)

def formatar_cpf(valor):
    d = re.sub(r'\D','',valor)
    return f'{d[:3]}.{d[3:6]}.{d[6:9]}-{d[9:]}' if len(d)==11 else valor


def texto(c, x, y, valor, tamanho=9, largura=None):
    c.setFont('Helvetica', tamanho)
    valor = str(valor or '')
    if largura:
        while valor and stringWidth(valor,'Helvetica',tamanho)>largura:
            valor=valor[:-1]
        if valor != str(valor or ''):
            valor+='…'
    c.drawString(x,y,valor)


def linha(c, x, y, rotulo, valor, largura=440):
    texto(c,x,y,rotulo,9)
    deslocamento=stringWidth(rotulo,'Helvetica',9)+8
    texto(c,x+deslocamento,y,valor,9,largura-deslocamento)
    c.line(x+deslocamento,y-3,x+largura,y-3)


def bloco(c, x, topo, largura, altura, titulo):
    c.rect(x,topo-altura,largura,altura)
    c.setFillColor(colors.white)
    c.rect(x+9,topo-5,stringWidth(titulo,'Helvetica-Bold',9)+10,12,fill=1,stroke=0)
    c.setFillColor(colors.black)
    c.setFont('Helvetica-Bold',9)
    c.drawString(x+14,topo-1,titulo)


def desenhar_ocorrencia(c, item, topo, altura, compacto=False):
    """Formulário A5 vertical (metade de A4), com grade fixa e sem sobreposição."""
    from reportlab.lib.utils import simpleSplit
    x, w = 34, A4[0] - 68
    preto = colors.HexColor('#202020')
    cinza = colors.HexColor('#626262')
    borda = colors.HexColor('#B9BFC5')
    fundo = colors.HexColor('#EFF1F3')
    pad = 12

    def texto(txt, px, baseline, maxw, size=8.1, bold=False, lines=1):
        fonte = 'Helvetica-Bold' if bold else 'Helvetica'
        raw = str(txt or '—')
        partes = simpleSplit(raw, fonte, size, maxw) or ['—']
        c.setFillColor(preto)
        c.setFont(fonte, size)
        for i, linha in enumerate(partes[:lines]):
            if i == lines-1 and len(partes)>lines:
                while linha and stringWidth(linha+'...', fonte, size)>maxw:
                    linha=linha[:-1]
                linha+='...'
            c.drawString(px,baseline-i*10,linha)

    def campo(rotulo, conteudo, px, label_y, largura, linhas=1):
        c.setFillColor(cinza)
        c.setFont('Helvetica-Bold',6.3)
        c.drawString(px,label_y,rotulo.upper())
        texto(conteudo,px,label_y-13,largura,8.2,lines=linhas)

    def cartao(y, h, titulo):
        c.setStrokeColor(borda)
        c.setLineWidth(.7)
        c.setFillColor(colors.white)
        c.roundRect(x,y-h,w,h,6,fill=1,stroke=1)
        c.setFillColor(fundo)
        c.roundRect(x+0.6,y-24,w-1.2,23,5,fill=1,stroke=0)
        c.rect(x+0.6,y-24,w-1.2,12,fill=1,stroke=0)
        c.setFillColor(preto)
        c.setFont('Helvetica-Bold',8.3)
        c.drawString(x+pad,y-16,titulo)

    empresa=str(item.get('empresa',''))
    m=re.match(r'^(\d{2}\.\d{3}\.\d{3}/\d{4}-\d{2})\s*-\s*(.*)$',empresa)
    cnpj,razao=(m.group(1),m.group(2)) if m else (EMPRESAS.get(empresa_normalizada(empresa),''),empresa)
    if not cnpj:
        cnpj=str(item.get('cnpj',''))
    # Cabeçalho com todos os dados do empregador dentro da mesma moldura.
    cab_h=79
    c.setStrokeColor(borda)
    c.setFillColor(colors.white)
    c.roundRect(x,topo-cab_h,w,cab_h,6,fill=1,stroke=1)
    logo=BASE/'LogodaMarca.png'
    try:
        img=ImageReader(str(logo)) if logo.exists() else ImageReader(io.BytesIO(recurso_embutido(LOGO_EMBUTIDO)))
        c.drawImage(img,x+12,topo-48,width=68,height=39,preserveAspectRatio=True,anchor='c',mask='auto')
    except Exception: pass
    texto('CORREÇÕES E LANÇAMENTOS MANUAIS',x+92,topo-19,w-106,10.3,bold=True)
    texto('FORMULÁRIO DE OCORRÊNCIA DE PONTO',x+92,topo-32,w-106,7)
    c.setStrokeColor(borda)
    c.line(x+pad,topo-54,x+w-pad,topo-54)
    campo('Empresa',razao,x+pad,topo-65,w*.66-25)
    campo('CNPJ',cnpj,x+w*.70,topo-65,w*.30-15)

    y=topo-88
    cartao(y,78,'01  |  IDENTIFICAÇÃO DO COLABORADOR')
    campo('Nome completo',item.get('nome'),x+pad,y-35,w-2*pad)
    campo('Cargo',item.get('cargo'),x+pad,y-59,w*.66-22)
    campo('CPF',formatar_cpf(item.get('cpf','')),x+w*.70,y-59,w*.30-15)

    y-=86
    cartao(y,91,'02  |  DADOS DA OCORRÊNCIA')
    data=item.get('data')
    hora=item.get('hora')
    data=data.strftime('%d/%m/%Y') if hasattr(data,'strftime') else str(data or '')
    hora=hora.strftime('%H:%M') if hasattr(hora,'strftime') else str(hora or '')
    campo('Data',data,x+pad,y-35,105)
    campo('Horário devido',hora,x+150,y-35,120)
    campo('Registro não marcado',item.get('registro'),x+285,y-35,w-300)
    c.setStrokeColor(borda)
    c.line(x+pad,y-56,x+w-pad,y-56)
    campo('Justificativa',item.get('justificativa'),x+pad,y-67,w-2*pad,linhas=1)

    y-=99
    cartao(y,61,'03  |  ASSINATURAS')
    espac=12
    col=(w-2*pad-2*espac)/3
    for i,rotulo in enumerate(('COLABORADOR(A)','LÍDER RESPONSÁVEL','RECURSOS HUMANOS')):
        px=x+pad+i*(col+espac)
        c.setStrokeColor(cinza)
        c.line(px,y-46,px+col,y-46)
        c.setFillColor(cinza)
        c.setFont('Helvetica-Bold',6)
        c.drawString(px,y-56,rotulo)
    return y-61


def pdf(itens):
    memoria=io.BytesIO();c=canvas.Canvas(memoria,pagesize=A4)
    c.setTitle('GDS Logística - Ocorrência de Ponto')
    meio=A4[1]/2
    desenhar_ocorrencia(c,itens[0],A4[1]-18,meio-28,compacto=True)
    if len(itens)>1:
        c.setStrokeColor(colors.HexColor('#AAAAAA'));c.setDash(3,4)
        c.line(30,meio,A4[0]-30,meio);c.setDash()
        desenhar_ocorrencia(c,itens[1],meio-13,meio-25,compacto=True)
    c.save();return memoria.getvalue()


def _minutos(hora):
    h, m = map(int, hora.split(':'))
    return h * 60 + m


def _somar_minutos(hora, delta):
    return f'{(_minutos(hora) + delta) % 1440 // 60:02d}:{(_minutos(hora) + delta) % 60:02d}'


def _ocorrencias_jornada(brutas, eventos, intervalo_minutos=60):
    """Regras únicas para todas as pessoas; distingue I/P de D e batidas reais.

    Sugestões de horários não são comprovação de trabalho. Não inventar saída.
    """
    permitidos = {'MARCAÇÃO IDFACE/IDFLEX', 'MARCAÇÃO MOBILE/WEB', 'MERCADO'}
    tipos = ['Entrada', 'Saída Intervalo', 'Retorno Intervalo', 'Saída']
    incluidos = [(h, normal(m)) for h, e, m in eventos if e in ('I', 'P')]
    desconsiderados = [(h, normal(m)) for h, e, m in eventos if e == 'D']
    if not brutas:
        return []
    resultado = []
    # Quando a jornada tem quatro batidas efetivamente incluídas, um D extra
    # não constitui falta. Não confundir horários do dia seguinte.
    if len(incluidos) >= 4:
        for i, (h, motivo) in enumerate(incluidos):
            if motivo not in permitidos:
                resultado.append((tipos[min(i, 3)], h, 'MARCAÇÃO INSERIDA MANUALMENTE: ' + motivo))
        return resultado
    # Três batidas originais com a última desconsiderada por 'entrada sem saída':
    # o relógio reconheceu o horário, mas o tratamento não o validou.
    # Solicitar conferência da saída; nunca inferir retorno do intervalo.
    if len(brutas) == 3 and len(incluidos) == 2 and desconsiderados:
        h_d, motivo_d = desconsiderados[-1]
        if h_d == brutas[-1] and ('SEM SAÍDA' in motivo_d or 'SEM SAIDA' in motivo_d):
            if _minutos(h_d) < 8 * 60 and _minutos(brutas[0]) >= 16 * 60:
                resultado.append(('Saída', h_d, 'SAÍDA FINAL DESCONSIDERADA — conferir jornada noturna'))
            else:
                resultado.append(('Retorno Intervalo', _somar_minutos(brutas[1], intervalo_minutos),
                                  'RETORNO DO INTERVALO AUSENTE — última batida é saída final desconsiderada; conferir'))
        else:
            resultado.append(('Registro a conferir', brutas[-1], 'JORNADA INCOMPLETA — batida desconsiderada; verificar posição'))
    elif len(brutas) == 3:
        a, b, c = brutas
        ab = (_minutos(b) - _minutos(a)) % 1440
        bc = (_minutos(c) - _minutos(b)) % 1440
        if 35 <= ab <= 105 and bc > 105:
            # Entrada, saída para intervalo, saída final: retorno ausente.
            resultado.append(('Retorno Intervalo', _somar_minutos(b, intervalo_minutos),
                              'RETORNO DO INTERVALO AUSENTE — sugestão pelo intervalo de 1 hora'))
        elif 35 <= bc <= 105 and ab > 105:
            # Entrada, retorno de intervalo, saída final: saída intervalo ausente.
            resultado.append(('Saída Intervalo', _somar_minutos(b, -intervalo_minutos),
                              'SAÍDA DO INTERVALO AUSENTE — sugestão pelo intervalo de 1 hora'))
        elif ab > 105 and bc > 105:
            # Distinguir pelo horário relativo: a terceira batida perto da saída
            # prevista pode ser saída final; nunca tratá-la como retorno.
            resultado.append(('Retorno Intervalo', _somar_minutos(b, intervalo_minutos),
                              'JORNADA COM TRÊS BATIDAS — retorno sugerido; conferir escala'))
        else:
            resultado.append(('Registro a conferir', c,
                              'JORNADA COM TRÊS BATIDAS — conferir posição da marcação ausente'))
    elif len(brutas) in (1, 2):
        resultado.append(('Registro a conferir', brutas[-1],
                          'JORNADA INCOMPLETA — conferir marcações e escala; horário provisório'))
    # Motivos inseridos manualmente não autorizados devem aparecer mesmo que
    # também haja falta de outra marcação, sem duplicar a mesma ocorrência.
    for i, (h, motivo) in enumerate(incluidos):
        if motivo not in permitidos:
            tipo = tipos[min(i, 3)]
            if not any(x[1] == h and x[0] == tipo for x in resultado):
                resultado.append((tipo, h, 'MARCAÇÃO INSERIDA MANUALMENTE: ' + motivo))
    return resultado


def extrair_espelho(conteudo):
    """Extrai ocorrências com base nas batidas reais e tratamentos do PDF.

    Não gera ocorrências no dia atual, em dias vazios ou a partir de
    registros (D) isolados. Aceita múltiplas ocorrências por jornada.
    """
    pessoas = {}
    hoje = datetime.now(ZoneInfo('America/Sao_Paulo')).date()
    with fitz.open(stream=conteudo, filetype='pdf') as doc:
        for pagina in doc:
            txt = pagina.get_text(sort=False)
            def obter(rotulo):
                m = re.search(r'(?m)^' + re.escape(rotulo) + r':\s*(.+)$', txt)
                return m.group(1).strip() if m else ''
            nome = normal(obter('NOME'))
            if not nome:
                continue
            empresa = empresa_normalizada(obter('EMPRESA'))
            cpf = numeros(obter('CPF'))
            cnpj = obter('CNPJ') or EMPRESAS.get(empresa, '')
            cargo = normal(obter('CARGO'))
            pessoa = pessoas.setdefault(nome, dict(empresa=empresa, cnpj=cnpj, cpf=cpf,
                                                    cargo=cargo, ocorrencias=[]))
            partes = re.split(r'(?m)^(\d{2}/\d{2}/\d{2})\s*-\s*[A-ZÇ]{3}\s*$', txt)
            for n in range(1, len(partes)-1, 2):
                try:
                    dia = datetime.strptime(partes[n], '%d/%m/%y').date()
                except ValueError:
                    continue
                if dia >= hoje:
                    continue
                bloco = partes[n+1].split('(I)=Incluído')[0]
                linhas = [l.strip() for l in bloco.splitlines() if l.strip()]
                if not linhas:
                    continue
                # A primeira linha contém apenas as marcações ORIGINAIS.
                # As linhas seguintes são a jornada tratada e seus motivos.
                primeira = linhas[0]
                brutas = re.findall(r'(?<!\d)\d{2}:\d{2}(?!\d)', primeira)
                if not brutas:
                    continue
                eventos = []
                for j in range(1, len(linhas)-2):
                    if (re.fullmatch(r'\d{2}:\d{2}', linhas[j])
                            and linhas[j+1] in ('I', 'D', 'P')):
                        eventos.append((linhas[j], linhas[j+1], linhas[j+2]))
                # Duplicidades no espelho (D) são ignoradas: não implicam
                # que alguma das quatro batidas esteja faltando.
                encontrados = _ocorrencias_jornada(brutas, eventos)
                vistos = set()
                for registro, hora_sugerida, motivo in encontrados:
                    chave = (registro, hora_sugerida, motivo)
                    if chave in vistos:
                        continue
                    vistos.add(chave)
                    try:
                        hora_obj = datetime.strptime(hora_sugerida, '%H:%M').time()
                    except ValueError:
                        continue
                    origem = (f'{motivo} — {registro} sugerido às {hora_sugerida}; '
                              f'marcações originais: {", ".join(brutas)}')
                    pessoa['ocorrencias'].append(dict(data=dia, registro=registro,
                                                       hora=hora_obj, origem=origem))
    return pessoas


def pdf_em_lote(itens):
    memoria=io.BytesIO()
    c=canvas.Canvas(memoria,pagesize=A4)
    c.setTitle('GDS Logística - Ocorrências automáticas')
    meio=A4[1]/2
    for i,item in enumerate(itens):
        if i and i%2==0:c.showPage()
        topo=A4[1]-18 if i%2==0 else meio-13
        desenhar_ocorrencia(c,item,topo,meio-28,compacto=True)
        if i%2==0 and i+1<len(itens):
            c.setStrokeColor(colors.HexColor('#AAAAAA'));c.setDash(3,4)
            c.line(30,meio,A4[0]-30,meio);c.setDash()
    c.save()
    return memoria.getvalue()


